package com.kisanmitra.order;
import com.kisanmitra.listing.*; import com.kisanmitra.user.User; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/orders") @RequiredArgsConstructor public class OrderController { private final OrderRepository orders; private final ListingRepository listings;
 @PostMapping public ResponseEntity<?> create(@RequestBody Map<String,Object>b,Authentication a){User u=user(a);Listing l=listings.findById(UUID.fromString((String)b.get("listing"))).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));Order o=new Order();o.setListing(l);o.setBuyer(u);o.setSeller(l.getSeller());o.setAgreedPrice(((Number)b.getOrDefault("agreedPrice",l.getPrice())).doubleValue());o.setQuantity(((Number)b.getOrDefault("quantity",l.getQuantity())).doubleValue());o.setUnit((String)b.getOrDefault("unit",l.getUnit()));o.setTotalAmount(o.getAgreedPrice()*o.getQuantity());return ResponseEntity.status(201).body(Map.of("success",true,"data",orders.save(o)));}
 @GetMapping("/me") public Map<String,Object> mine(Authentication a){User u=user(a);return Map.of("success",true,"data",orders.findByBuyerIdOrSellerIdOrderByCreatedAtDesc(u.getId(),u.getId()));}
 @GetMapping("/{id}") public Map<String,Object> one(@PathVariable UUID id,Authentication a){Order o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));User u=user(a);if(!o.getBuyer().getId().equals(u.getId())&&!o.getSeller().getId().equals(u.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return Map.of("success",true,"data",o);}
 @PutMapping("/{id}/status") public Map<String,Object> status(@PathVariable UUID id,@RequestBody Map<String,String>b,Authentication a){Order o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!o.getSeller().getId().equals(user(a).getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);o.setStatus(b.getOrDefault("status",o.getStatus()));return Map.of("success",true,"data",orders.save(o));}
 private User user(Authentication a){if(a==null||!(a.getPrincipal() instanceof User u))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return u;}}
